private func formatAdhanCutTime(_ time: TimeInterval) -> String {
    let minutes = Int(max(0, time)) / 60
    let seconds = max(0, time) - Double(minutes * 60)
    return localizedInterfaceDigits(String(format: "%d:%04.1f", minutes, seconds))
}

private func adhanCutSummary(for target: AdhanCutTarget) -> String {
    guard let cut = adhanAudioCut(for: target) else {
        return "\(adhanStudioText("full")) · \(adhanStudioText("edit"))"
    }
    if let displayName = cut.displayName, !displayName.isEmpty {
        return "\(displayName) · \(adhanStudioText("edit"))"
    }
    if cut.ranges.count > 1 {
        let sections = String(format: adhkarModeText("studio.kept"),
                              cut.ranges.count)
        return "\(sections) · \(adhanStudioText("edit"))"
    }
    return "\(formatAdhanCutTime(cut.start))–\(formatAdhanCutTime(cut.end)) · \(adhanStudioText("edit"))"
}

/// Streams an audio file once and reduces it to peak buckets for drawing.
/// Never loads the decoded PCM of a long recording into memory at once.
private func loadAdhkarWaveform(url: URL, buckets: Int = 640,
                                completion: @escaping ([Float], TimeInterval) -> Void) {
    DispatchQueue.global(qos: .userInitiated).async {
        guard let file = try? AVAudioFile(forReading: url), file.length > 0,
              let buffer = AVAudioPCMBuffer(pcmFormat: file.processingFormat,
                                            frameCapacity: 1 << 16) else {
            DispatchQueue.main.async { completion([], 0) }
            return
        }
        let totalFrames = Int(file.length)
        let duration = Double(totalFrames) / file.processingFormat.sampleRate
        let bucketSize = max(1, totalFrames / buckets)
        var peaks: [Float] = []
        peaks.reserveCapacity(buckets + 2)
        var currentPeak: Float = 0
        var framesInBucket = 0
        while file.framePosition < file.length {
            buffer.frameLength = 0
            guard (try? file.read(into: buffer)) != nil, buffer.frameLength > 0,
                  let data = buffer.floatChannelData?[0] else { break }
            for frame in 0..<Int(buffer.frameLength) {
                currentPeak = max(currentPeak, abs(data[frame]))
                framesInBucket += 1
                if framesInBucket >= bucketSize {
                    peaks.append(currentPeak)
                    currentPeak = 0
                    framesInBucket = 0
                }
            }
        }
        if framesInBucket > 0 { peaks.append(currentPeak) }
        DispatchQueue.main.async { completion(peaks, duration) }
    }
}

/// Interactive waveform strip: draggable start/end handles select the window
/// of the recording that belongs to one dhikr; clicking anywhere scrubs the
/// preview playhead. Timeline runs left→right in every UI language, like
/// every audio editor.
final class AdhkarWaveformView: NSView {
    var samples: [Float] = [] { didSet { needsDisplay = true } }
    var duration: TimeInterval = 0 { didSet { needsDisplay = true } }
    /// Non-destructive cutouts. They remain visible while the user selects
    /// another middle section, making repeated edits easy to understand.
    var removedRanges: [ClosedRange<TimeInterval>] = [] {
        didSet { needsDisplay = true }
    }
    /// Adhkar editing keeps cutouts visible for auditability. Adhan editing
    /// uses a result-first view: removed time collapses and the retained
    /// samples are drawn as one continuous waveform, exactly like the file
    /// that Save exports.
    var collapsesRemovedRanges = false { didSet { needsDisplay = true } }
    var selectionStart: TimeInterval = 0 {
        didSet { needsDisplay = true; onSelectionChange?() }
    }
    var selectionEnd: TimeInterval = 0 {
        didSet { needsDisplay = true; onSelectionChange?() }
    }
    var playhead: TimeInterval? { didSet { needsDisplay = true } }
    var onSelectionChange: (() -> Void)?
    var onSeek: ((TimeInterval) -> Void)?
    var onRemoveSelection: (() -> Void)?
    var onKeepSelection: (() -> Void)?

    private enum DragTarget { case none, start, end }
    private var dragging = DragTarget.none

    private var plotRect: NSRect { bounds.insetBy(dx: 10, dy: 8) }

    private var retainedRanges: [ClosedRange<TimeInterval>] {
        guard duration > 0, collapsesRemovedRanges else {
            return duration > 0 ? [0...duration] : []
        }
        let removed = removedRanges.sorted { $0.lowerBound < $1.lowerBound }
        var retained: [ClosedRange<TimeInterval>] = []
        var cursor: TimeInterval = 0
        for range in removed {
            let start = max(0, min(duration, range.lowerBound))
            let end = max(0, min(duration, range.upperBound))
            if start - cursor >= 0.001 { retained.append(cursor...start) }
            cursor = max(cursor, end)
        }
        if duration - cursor >= 0.001 { retained.append(cursor...duration) }
        return retained
    }

    var editedDuration: TimeInterval {
        retainedRanges.reduce(0) { $0 + ($1.upperBound - $1.lowerBound) }
    }

    /// Maps a source timestamp to its position in the collapsed result.
    /// Timestamps inside a deleted range resolve to that edit's stitch point.
    func resultTime(for sourceTime: TimeInterval) -> TimeInterval {
        guard collapsesRemovedRanges else { return sourceTime }
        let time = max(0, min(duration, sourceTime))
        var result: TimeInterval = 0
        for range in retainedRanges {
            if time < range.lowerBound { return result }
            if time <= range.upperBound {
                return result + time - range.lowerBound
            }
            result += range.upperBound - range.lowerBound
        }
        return result
    }

    private func sourceTime(forResultTime resultTime: TimeInterval)
        -> TimeInterval {
        guard collapsesRemovedRanges else { return resultTime }
        var remaining = max(0, min(editedDuration, resultTime))
        for range in retainedRanges {
            let length = range.upperBound - range.lowerBound
            if remaining <= length { return range.lowerBound + remaining }
            remaining -= length
        }
        return retainedRanges.last?.upperBound ?? 0
    }

    private func xFor(_ time: TimeInterval) -> CGFloat {
        let visibleDuration = collapsesRemovedRanges ? editedDuration : duration
        guard visibleDuration > 0 else { return plotRect.minX }
        let visibleTime = collapsesRemovedRanges ? resultTime(for: time) : time
        return plotRect.minX + plotRect.width *
            CGFloat(visibleTime / visibleDuration)
    }

    private func timeFor(_ x: CGFloat) -> TimeInterval {
        let visibleDuration = collapsesRemovedRanges ? editedDuration : duration
        guard visibleDuration > 0, plotRect.width > 0 else { return 0 }
        let fraction = max(0, min(1, (x - plotRect.minX) / plotRect.width))
        let resultTime = TimeInterval(fraction) * visibleDuration
        return sourceTime(forResultTime: resultTime)
    }

    override func draw(_ dirtyRect: NSRect) {
        let isDark = effectiveAppearance.bestMatch(from: [.darkAqua, .vibrantDark]) != nil
        let backdrop = NSBezierPath(roundedRect: bounds, xRadius: 8, yRadius: 8)
        (isDark ? NSColor(white: 0.16, alpha: 1) : NSColor(white: 0.94, alpha: 1)).setFill()
        backdrop.fill()
        guard !samples.isEmpty, duration > 0 else {
            let paragraph = NSMutableParagraphStyle()
            paragraph.alignment = .center
            NSAttributedString(string: adhkarModeText("studio.empty"), attributes: [
                .font: Localizer.shared.font(size: 12),
                .foregroundColor: NSColor.secondaryLabelColor,
                .paragraphStyle: paragraph,
            ]).draw(in: NSRect(x: 0, y: bounds.midY - 9, width: bounds.width, height: 18))
            return
        }
        let plot = plotRect
        let midY = plot.midY
        let visibleSamples: [(Int, Float)] = samples.enumerated().compactMap {
            element in
            let index = element.offset
            guard collapsesRemovedRanges else {
                return (index, element.element)
            }
            let sampleTime = duration * TimeInterval(index) /
                TimeInterval(samples.count)
            return removedRanges.contains { $0.contains(sampleTime) }
                ? nil : (index, element.element)
        }
        let barWidth = plot.width / CGFloat(max(1, visibleSamples.count))
        let peak = max(0.05, CGFloat(samples.max() ?? 1))

        // Selection band first, then bars over it.
        let selX0 = xFor(selectionStart)
        let selX1 = xFor(selectionEnd)
        NSColor.appGreenAccent.withAlphaComponent(isDark ? 0.22 : 0.16).setFill()
        NSRect(x: selX0, y: bounds.minY + 2, width: max(0, selX1 - selX0),
               height: bounds.height - 4).fill()

        // Removed sections sit above the general selection tint. A warm,
        // translucent treatment reads as a cut without hiding the waveform.
        if !collapsesRemovedRanges {
            for range in removedRanges {
                let x0 = xFor(range.lowerBound)
                let x1 = xFor(range.upperBound)
                NSColor.systemRed.withAlphaComponent(
                    isDark ? 0.25 : 0.18).setFill()
                NSRect(x: x0, y: bounds.minY + 2,
                       width: max(1, x1 - x0),
                       height: bounds.height - 4).fill()
            }
        }

        for (visibleIndex, element) in visibleSamples.enumerated() {
            let (sourceIndex, sample) = element
            let x = plot.minX + CGFloat(visibleIndex) * barWidth
            let sampleTime = duration * TimeInterval(sourceIndex) /
                TimeInterval(samples.count)
            let inSelection = sampleTime >= selectionStart &&
                sampleTime <= selectionEnd
            let isRemoved = removedRanges.contains { $0.contains(sampleTime) }
            let height = max(1.2, plot.height * 0.48 * CGFloat(sample) / peak)
            (isRemoved
                ? NSColor.systemRed.withAlphaComponent(0.38)
                : (inSelection
                    ? NSColor.appGreenAccent
                    : NSColor.secondaryLabelColor.withAlphaComponent(0.55))).setFill()
            NSRect(x: x, y: midY - height, width: max(0.8, barWidth - 0.6),
                   height: height * 2).fill()
        }

        // A subtle seam marks where retained ranges were physically joined.
        // It is informational only; no deleted samples remain on screen.
        if collapsesRemovedRanges, retainedRanges.count > 1,
           editedDuration > 0 {
            var elapsed: TimeInterval = 0
            for range in retainedRanges.dropLast() {
                elapsed += range.upperBound - range.lowerBound
                let x = plot.minX + plot.width *
                    CGFloat(elapsed / editedDuration)
                NSColor.separatorColor.withAlphaComponent(0.75).setFill()
                NSRect(x: x - 0.5, y: plot.minY,
                       width: 1, height: plot.height).fill()
            }
        }

        // Handles.
        for (time, isStart) in [(selectionStart, true), (selectionEnd, false)] {
            let x = xFor(time)
            NSColor.appGreenAccent.setFill()
            NSRect(x: x - 1, y: bounds.minY + 2, width: 2, height: bounds.height - 4).fill()
            let grip = NSBezierPath(ovalIn: NSRect(x: x - 5,
                                                   y: isStart ? bounds.maxY - 14 : bounds.minY + 4,
                                                   width: 10, height: 10))
            grip.fill()
            NSColor.white.withAlphaComponent(0.85).setStroke()
            grip.lineWidth = 1
            grip.stroke()
        }

        // Playhead.
        if let playhead {
            NSColor.systemRed.withAlphaComponent(0.9).setFill()
            NSRect(x: xFor(playhead) - 0.75, y: bounds.minY + 2,
                   width: 1.5, height: bounds.height - 4).fill()
        }
    }

    override func mouseDown(with event: NSEvent) {
        let point = convert(event.locationInWindow, from: nil)
        let startX = xFor(selectionStart)
        let endX = xFor(selectionEnd)
        if abs(point.x - startX) < 7 { dragging = .start }
        else if abs(point.x - endX) < 7 { dragging = .end }
        else {
            dragging = .none
            let time = timeFor(point.x)
            playhead = time
            onSeek?(time)
        }
    }

    override func mouseDragged(with event: NSEvent) {
        let point = convert(event.locationInWindow, from: nil)
        let time = timeFor(point.x)
        switch dragging {
        case .start: selectionStart = min(time, selectionEnd - 0.15)
        case .end:   selectionEnd = max(time, selectionStart + 0.15)
        case .none:
            playhead = time
            onSeek?(time)
        }
    }

    override func mouseUp(with event: NSEvent) { dragging = .none }

    /// Contextual edit actions appear only when the pointer is over the
    /// highlighted In/Out range. This keeps a normal right-click elsewhere
    /// from implying that an unselected part of the recording will change.
    override func menu(for event: NSEvent) -> NSMenu? {
        guard duration > 0,
              selectionEnd - selectionStart >= 0.05,
              onRemoveSelection != nil || onKeepSelection != nil else {
            return nil
        }
        let point = convert(event.locationInWindow, from: nil)
        let selectedRect = NSRect(x: xFor(selectionStart),
                                  y: bounds.minY,
                                  width: max(0, xFor(selectionEnd) -
                                             xFor(selectionStart)),
                                  height: bounds.height)
        guard selectedRect.insetBy(dx: -2, dy: 0).contains(point) else {
            return nil
        }

        let menu = NSMenu()
        let remove = NSMenuItem(title: adhkarModeText("studio.remove"),
                                action: #selector(removeSelectionFromMenu),
                                keyEquivalent: "")
        remove.target = self
        remove.image = templateSymbol("scissors", pointSize: 12)
        remove.isEnabled = onRemoveSelection != nil
        menu.addItem(remove)

        let keep = NSMenuItem(title: adhkarModeText("studio.keep"),
                              action: #selector(keepSelectionFromMenu),
                              keyEquivalent: "")
        keep.target = self
        keep.image = templateSymbol("selection.pin.in.out", pointSize: 12)
        keep.isEnabled = onKeepSelection != nil
        menu.addItem(keep)
        return menu
    }

    @objc private func removeSelectionFromMenu() {
        onRemoveSelection?()
    }

    @objc private func keepSelectionFromMenu() {
        onKeepSelection?()
    }
}

/// The Audio Studio: split one long recording into per-dhikr segments, or
/// re-trim an existing item's audio. Trims are non-destructive — a segment
/// is stored as `audioRef#start-end` and playback honours the window — so a
/// single imported file can back an entire collection.
final class AdhkarAudioStudioController: NSViewController {
    /// Called when "Add as new dhikr" creates an entry for the collection.
    var onCreateEntry: ((AdhkarEntry) -> Void)?
    /// Called when a segment is applied to an existing item.
    var onAssignAudio: ((UUID, String) -> Void)?
    /// Items of the target collection (for the assign popup).
    var collectionItems: [(id: UUID, title: String)] = []
    /// Preselect this audio (e.g. re-trim an existing item's source).
    var initialRef: String?

    private var sourcePopup: NSPopUpButton!
    private var waveform: AdhkarWaveformView!
    private var selectionLabel: NSTextField!
    private var playheadLabel: NSTextField!
    private var previewButton: NSButton!
    private var arabicField: NSTextField!
    private var countField: NSTextField!
    private var countStepper: NSStepper!
    private var assignPopup: NSPopUpButton!
    private var addButton: NSButton!
    private var editStatusLabel: NSTextField!
    private var undoButton: NSButton!

    private var options: [AdhkarAudioOption] = []
    private var currentBaseRef: String?
    private var previewPlayer: AVAudioPlayer?
    private var previewTimer: Timer?
    private var previewSegments: [ClosedRange<TimeInterval>] = []
    private var previewSegmentIndex = 0

    /// `false` preserves the original "selection becomes the clip" workflow.
    /// It becomes true after a keep/remove/reset action or when reopening an
    /// already edited ref, at which point every retained range is serialized.
    private var hasEditedSegments = false
    private var keptSegments: [ClosedRange<TimeInterval>] = []
    private var editHistory: [([ClosedRange<TimeInterval>], Bool)] = []

    deinit {
        previewTimer?.invalidate()
        previewPlayer?.stop()
    }

